"""Lexer and recursive-descent parser for minisql's SELECT subset."""
from dataclasses import dataclass


@dataclass(frozen=True)
class Expr:
    """Expression node. ``kind`` is one of literal/column/unary/binary/
    is_null/in/between/like/call; ``raw`` preserves its query spelling."""
    kind: str
    value: object = None
    args: tuple = ()
    raw: str = ""


@dataclass(frozen=True)
class Star:
    """The special star argument to COUNT, or a wildcard select item."""


@dataclass(frozen=True)
class SelectItem:
    expr: Expr
    alias: object = None


@dataclass(frozen=True)
class OrderItem:
    expr: Expr
    descending: bool = False


@dataclass(frozen=True)
class Query:
    distinct: bool
    columns: tuple
    table: str
    where: object = None
    group_by: tuple = ()
    having: object = None
    order_by: tuple = ()
    limit: object = None
    offset: int = 0


class ParseError(ValueError):
    """Invalid SQL syntax."""


KEYWORDS = {
    "SELECT", "DISTINCT", "FROM", "WHERE", "GROUP", "BY", "HAVING",
    "ORDER", "ASC", "DESC", "LIMIT", "OFFSET", "AS", "AND", "OR",
    "NOT", "IN", "BETWEEN", "LIKE", "IS", "NULL", "TRUE", "FALSE",
}


@dataclass(frozen=True)
class Token:
    kind: str
    value: object
    start: int
    end: int


def _lex(sql):
    out = []
    i, n = 0, len(sql)
    while i < n:
        c = sql[i]
        if c.isspace():
            i += 1
            continue
        start = i
        if c == "'":
            i += 1
            chars = []
            while i < n:
                if sql[i] == "'":
                    if i + 1 < n and sql[i + 1] == "'":
                        chars.append("'")
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    chars.append(sql[i])
                    i += 1
            else:
                raise ParseError("unterminated string literal")
            out.append(Token("LITERAL", "".join(chars), start, i))
            continue
        if c == '"':
            i += 1
            chars = []
            while i < n:
                if sql[i] == '"':
                    if i + 1 < n and sql[i + 1] == '"':
                        chars.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    chars.append(sql[i])
                    i += 1
            else:
                raise ParseError("unterminated quoted name")
            out.append(Token("IDENT", "".join(chars), start, i))
            continue
        if c.isdigit() or (c == "." and i + 1 < n and sql[i + 1].isdigit()):
            j = i
            while j < n and sql[j].isdigit():
                j += 1
            decimal = False
            if j < n and sql[j] == ".":
                decimal = True
                j += 1
                while j < n and sql[j].isdigit():
                    j += 1
            text = sql[i:j]
            val = float(text) if decimal else int(text)
            out.append(Token("LITERAL", val, start, j))
            i = j
            continue
        if c.isalpha() or c == "_":
            i += 1
            while i < n and (sql[i].isalnum() or sql[i] == "_"):
                i += 1
            word = sql[start:i]
            upper = word.upper()
            if upper in ("NULL", "TRUE", "FALSE"):
                val = {"NULL": None, "TRUE": True, "FALSE": False}[upper]
                out.append(Token("LITERAL", val, start, i))
            elif upper in KEYWORDS:
                out.append(Token("KW", upper, start, i))
            else:
                out.append(Token("IDENT", word, start, i))
            continue
        two = sql[i:i + 2]
        if two in ("!=", "<>", "<=", ">=", "||"):
            out.append(Token("OP", two, i, i + 2))
            i += 2
            continue
        if c in "=<>+-*/(),;":
            out.append(Token("PUNC" if c in "(),;" else "OP", c, i, i + 1))
            i += 1
            continue
        raise ParseError("unexpected character %r at position %d" % (c, i))
    out.append(Token("EOF", None, n, n))
    return out


class _Parser:
    def __init__(self, sql):
        self.sql = sql
        self.tokens = _lex(sql)
        self.i = 0

    @property
    def t(self):
        return self.tokens[self.i]

    def take(self):
        t = self.t
        self.i += 1
        return t

    def is_kw(self, word):
        return self.t.kind == "KW" and self.t.value == word

    def accept_kw(self, word):
        if self.is_kw(word):
            return self.take()
        return None

    def accept(self, value):
        if self.t.value == value:
            return self.take()
        return None

    def expect_kw(self, word):
        if not self.accept_kw(word):
            self.fail("expected " + word)

    def expect(self, value):
        if not self.accept(value):
            self.fail("expected %r" % value)

    def fail(self, message):
        raise ParseError("%s at position %d" % (message, self.t.start))

    def identifier(self):
        if self.t.kind != "IDENT":
            self.fail("expected name")
        return self.take().value

    def parse(self):
        self.expect_kw("SELECT")
        distinct = bool(self.accept_kw("DISTINCT"))
        columns = []
        if self.accept("*"):
            columns.append(Star())
        else:
            while True:
                expr = self.expression()
                alias = None
                if self.accept_kw("AS"):
                    alias = self.identifier()
                elif self.t.kind == "IDENT":
                    alias = self.take().value
                columns.append(SelectItem(expr, alias))
                if not self.accept(","):
                    break
        self.expect_kw("FROM")
        table = self.identifier()
        where = self.expression() if self.accept_kw("WHERE") else None
        group = []
        if self.accept_kw("GROUP"):
            self.expect_kw("BY")
            group.append(self.expression())
            while self.accept(","):
                group.append(self.expression())
        having = self.expression() if self.accept_kw("HAVING") else None
        order = []
        if self.accept_kw("ORDER"):
            self.expect_kw("BY")
            while True:
                e = self.expression()
                descending = bool(self.accept_kw("DESC"))
                if not descending:
                    self.accept_kw("ASC")
                order.append(OrderItem(e, descending))
                if not self.accept(","):
                    break
        limit = offset = None
        if self.accept_kw("LIMIT"):
            if self.t.kind != "LITERAL" or isinstance(self.t.value, (str, bool)) or self.t.value is None or not isinstance(self.t.value, int):
                self.fail("LIMIT requires a non-negative integer")
            limit = self.take().value
            if limit < 0:
                self.fail("LIMIT requires a non-negative integer")
            if self.accept_kw("OFFSET"):
                if self.t.kind != "LITERAL" or not isinstance(self.t.value, int) or isinstance(self.t.value, bool) or self.t.value < 0:
                    self.fail("OFFSET requires a non-negative integer")
                offset = self.take().value
            else:
                offset = 0
        self.accept(";")
        if self.t.kind != "EOF":
            self.fail("unexpected token")
        return Query(distinct, tuple(columns), table, where, tuple(group), having,
                     tuple(order), limit, 0 if offset is None else offset)

    def expression(self):
        return self._or()

    def _node(self, kind, value, args, start):
        end = self.tokens[self.i - 1].end
        return Expr(kind, value, tuple(args), self.sql[start:end])

    def _or(self):
        left = self._and()
        while self.accept_kw("OR"):
            start = self._start(left)
            right = self._and()
            left = self._node("binary", "OR", (left, right), start)
        return left

    def _and(self):
        left = self._not()
        while self.accept_kw("AND"):
            start = self._start(left)
            right = self._not()
            left = self._node("binary", "AND", (left, right), start)
        return left

    def _not(self):
        if self.is_kw("NOT"):
            tok = self.take()
            child = self._not()
            return self._node("unary", "NOT", (child,), tok.start)
        return self._comparison()

    def _comparison(self):
        left = self._concat()
        negated = False
        if self.is_kw("NOT") and self.tokens[self.i + 1].value in ("IN", "BETWEEN", "LIKE"):
            self.take()
            negated = True
        if self.accept_kw("IS"):
            neg = bool(self.accept_kw("NOT"))
            self.expect_kw("NULL")
            return self._node("is_null", neg, (left,), self._start(left))
        if self.accept_kw("IN"):
            self.expect("(")
            if self.accept(")"):
                self.fail("IN list cannot be empty")
            items = [self.expression()]
            while self.accept(","):
                items.append(self.expression())
            self.expect(")")
            return self._node("in", negated, (left, *items), self._start(left))
        if self.accept_kw("BETWEEN"):
            low = self._concat()
            self.expect_kw("AND")
            high = self._concat()
            return self._node("between", negated, (left, low, high), self._start(left))
        if self.accept_kw("LIKE"):
            pattern = self._concat()
            return self._node("like", negated, (left, pattern), self._start(left))
        if negated:
            self.fail("expected IN, BETWEEN, or LIKE after NOT")
        if self.t.kind == "OP" and self.t.value in ("=", "!=", "<>", "<", "<=", ">", ">="):
            op = self.take()
            right = self._concat()
            return self._node("binary", op.value, (left, right), self._start(left))
        return left

    def _concat(self):
        left = self._sum()
        while self.accept("||"):
            start = self._start(left)
            right = self._sum()
            left = self._node("binary", "||", (left, right), start)
        return left

    def _sum(self):
        left = self._product()
        while self.t.value in ("+", "-") and self.t.kind == "OP":
            op = self.take().value
            right = self._product()
            left = self._node("binary", op, (left, right), self._start(left))
        return left

    def _product(self):
        left = self._unary()
        while self.t.value in ("*", "/") and self.t.kind == "OP":
            op = self.take().value
            right = self._unary()
            left = self._node("binary", op, (left, right), self._start(left))
        return left

    def _unary(self):
        if self.t.value == "-" and self.t.kind == "OP":
            tok = self.take()
            child = self._unary()
            return self._node("unary", "-", (child,), tok.start)
        return self._primary()

    def _primary(self):
        tok = self.t
        if tok.kind == "LITERAL":
            self.take()
            return Expr("literal", tok.value, (), self.sql[tok.start:tok.end])
        if tok.kind == "IDENT":
            name = self.take().value
            if self.accept("("):
                args = []
                if not self.accept(")"):
                    if self.accept("*"):
                        args.append(Star())
                        self.expect(")")
                    else:
                        args.append(self.expression())
                        while self.accept(","):
                            args.append(self.expression())
                        self.expect(")")
                return self._node("call", name, args, tok.start)
            return Expr("column", name, (), self.sql[tok.start:tok.end])
        if self.accept("("):
            start = tok.start
            e = self.expression()
            self.expect(")")
            # Preserve parentheses for expression-derived output labels.
            return Expr(e.kind, e.value, e.args, self.sql[start:self.tokens[self.i - 1].end])
        self.fail("expected expression")

    def _start(self, expr):
        # Find source position for a previously assembled child expression.
        return self.sql.find(expr.raw, 0, self.t.start + len(expr.raw))


def parse(sql):
    """Parse one query and return a :class:`Query`; raises ParseError."""
    return _Parser(sql).parse()

