"""Run SQL SELECT queries against CSV files. See SPEC.md."""

from .io import load_table
from .parser import parse
from .evaluator import evaluate, contains_aggregate, validate_aggregates


class QueryError(Exception):
    """Raised for any problem with a query."""


def run(sql, directory="."):
    """Run ``sql`` against the CSV files in ``directory``."""
    query = parse(sql)
    headers, source_rows = load_table(query.table, directory)
    # A row mapping retains the source spelling while evaluator performs
    # case-insensitive lookup.
    rows = [dict(zip(headers, values)) for values in source_rows]

    def has_agg(expr):
        return expr is not None and contains_aggregate(expr)

    grouped = bool(query.group_by) or any(
        has_agg(item.expr) for item in query.columns if hasattr(item, "expr")
    ) or has_agg(query.having) or any(has_agg(item.expr) for item in query.order_by)

    # Expand * before validation and evaluation.
    from .parser import Expr, SelectItem, Star
    items = []
    for item in query.columns:
        if item is Star or isinstance(item, Star):
            items.extend(SelectItem(Expr("column", h, raw=h), None) for h in headers)
        else:
            items.append(item)

    def check_group_expr(expr):
        if expr is None:
            return
        if expr.kind == "call" and str(expr.value).upper() in {"COUNT", "SUM", "AVG", "MIN", "MAX"}:
            return
        if expr in query.group_by:
            return
        if expr.kind == "column":
            raise QueryError("column must appear in GROUP BY or an aggregate")
        for child in expr.args:
            if isinstance(child, Expr):
                check_group_expr(child)

    for item in items:
        validate_aggregates(item.expr)
